package com.healthcare.entity;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="prescriptions") public class Prescription {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(optional=false) private Patient patient;@ManyToOne(optional=false) private Doctor doctor;@ManyToOne private Appointment appointment;@Column(nullable=false,length=4000) private String diagnosis;@Column(length=4000) private String notes;@Column(nullable=false,length=4000) private String medicines;@Column(nullable=false,updatable=false) private Instant createdAt=Instant.now();protected Prescription(){}public Prescription(Patient p,Doctor d,Appointment a,String diagnosis,String notes,String medicines){patient=p;doctor=d;appointment=a;this.diagnosis=diagnosis;this.notes=notes;this.medicines=medicines;}public Long getId(){return id;}public Patient getPatient(){return patient;}public Doctor getDoctor(){return doctor;}public Appointment getAppointment(){return appointment;}public String getDiagnosis(){return diagnosis;}public String getNotes(){return notes;}public String getMedicines(){return medicines;}public Instant getCreatedAt(){return createdAt;}}
